// Builds a REAL PSO workspace for the deployment demonstration, using only the public `pso` commands and the documented tutorial sources
// (docs/examples/spring-crud, the "Build a CRUD API" tutorial). Nothing in the framework is modified to make it pass.
//
//   node build-workspace.mjs <output-dir> [--skip-maven]
//
// Result: <out>/shop with   gateway (Node orchestrator)   catalog + inventory (Spring Boot, PostgreSQL, Flyway)   keys/ (ES256 JWKS)
// and, under <out>/artifacts, one deployable tarball per service (the Spring jars and the orchestrator with its @pso dependencies).
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(here, "..", "..", "..", "..", "..");
const PSO = join(REPO, "packages", "cli", "bin", "pso.js");
const EX = join(REPO, "packages", "cli", "docs", "examples", "spring-crud");
const out = resolve(process.argv[2] ?? "pso-real-workspace");
const skipMaven = process.argv.includes("--skip-maven");

const run = (cmd, args, cwd, label) => {
  const r = spawnSync(cmd, args, { cwd, encoding: "utf8", windowsHide: true, maxBuffer: 64 * 1024 * 1024, shell: process.platform === "win32" && /\.(cmd|bat)$|^npm$|^npx$/.test(cmd) });
  if (r.status !== 0) throw new Error(`${label ?? cmd + " " + args.join(" ")} failed (${r.status}):\n${(r.stdout ?? "") + (r.stderr ?? "")}`.slice(0, 4000));
  return r.stdout;
};
const pso = (args, cwd) => run(process.execPath, [PSO, ...args], cwd, `pso ${args.join(" ")}`);

rmSync(out, { recursive: true, force: true }); mkdirSync(out, { recursive: true });
pso(["create", "workspace", "shop", "--layout", "flat"], out);
const ws = join(out, "shop");
pso(["create", "service", "catalog", "--runtime", "spring-boot", "--db", "postgres", "--port", "8101", "--prefix", "/catalog"], ws);
pso(["create", "service", "inventory", "--runtime", "spring-boot", "--db", "postgres", "--port", "8102", "--prefix", "/inventory"], ws);
pso(["create", "orchestrator", "gateway", "--port", "3000"], ws);

// ---- the documented domain code: catalog = the tutorial's products; inventory = the same documented pattern for another domain
const rename = (text, map) => { let t = text; for (const [a, b] of map) t = t.split(a).join(b); return t; };
const INVENTORY = [["Products", "Items"], ["Product", "Item"], ["products", "items"], ["product", "item"], ["catalog", "inventory"], ["Catalog", "Inventory"]];
function copyTree(from, to, map) {
  for (const e of readdirSync(from, { withFileTypes: true })) {
    const dstName = map ? rename(e.name, map) : e.name; const s = join(from, e.name); const d = join(to, dstName);
    if (e.isDirectory()) { mkdirSync(d, { recursive: true }); copyTree(s, d, map); } else { mkdirSync(dirname(d), { recursive: true }); writeFileSync(d, map ? rename(readFileSync(s, "utf8"), map) : readFileSync(s)); }
  }
}
for (const [svc, map] of [["catalog", undefined], ["inventory", INVENTORY]]) {
  const main = join(ws, svc, "src", "main");
  copyTree(join(EX, "src", "main", "java"), join(main, "java"), map);
  copyTree(join(EX, "src", "main", "resources", "db"), join(main, "resources", "db"), map);
  // the shipped V1 placeholder of the template is replaced by the documented migration of the same version
  for (const f of readdirSync(join(main, "resources", "db", "migration"))) if (/^V1__/.test(f) && !/create_/.test(f)) rmSync(join(main, "resources", "db", "migration", f));
  const app = readFileSync(join(EX, "application.yml"), "utf8");
  writeFileSync(join(main, "resources", "application.yml"), map ? rename(app, map).replace(/\$\{PORT:8081\}/, "${PORT:8102}") : app.replace(/\$\{PORT:8081\}/, "${PORT:8101}"));
}
// the gateway: the documented routes of the tutorial (catalog), and the same module for inventory
const gw = join(ws, "gateway", "src", "routes");
copyTree(join(EX, "gateway", "src", "routes"), gw, undefined);
copyTree(join(EX, "gateway", "src", "routes"), gw, INVENTORY);
writeFileSync(join(ws, "gateway", ".env"), "PSO_JWT_ISSUER=https://shop.local\nPSO_JWT_AUDIENCE=shop-api\nPSO_JWT_JWKS_URI=http://127.0.0.1:8099/jwks.json\nPSO_JWT_ALGORITHMS=ES256\nPSO_WORKSPACE=../pso.workspace.json\n");

// ---- token issuer for the demonstration (the tutorial's own development tools), keys generated by the public command
pso(["security:keys", "--generate"], ws);
cpSync(join(EX, "dev-jwks.mjs"), join(ws, "dev-jwks.mjs")); cpSync(join(EX, "dev-token.mjs"), join(ws, "dev-token.mjs"));
pso(["validate"], ws);

if (!skipMaven) {
  const mvnw = process.platform === "win32" ? "mvnw.cmd" : "./mvnw";
  for (const svc of ["catalog", "inventory"]) run(join(ws, svc, mvnw), ["-q", "-B", "-DskipTests", "package"], join(ws, svc), `maven build of ${svc}`);
}
run("npm", ["install", "--no-audit", "--no-fund", "--no-progress"], join(ws, "gateway"), "npm install (gateway)");
run("npm", ["run", "build"], join(ws, "gateway"), "gateway build");

// ---- deployable artifacts: what a release pipeline would upload (a tarball per service)
const art = join(out, "artifacts"); mkdirSync(art, { recursive: true });
for (const svc of ["catalog", "inventory"]) {
  const stage = join(art, `${svc}-stage`); mkdirSync(stage, { recursive: true });
  const jar = readdirSync(join(ws, svc, "target")).find((f) => /^[a-z-]+-0\.1\.0\.jar$/.test(f)); if (!jar) throw new Error(`no jar for ${svc}`);
  cpSync(join(ws, svc, "target", jar), join(stage, "app.jar"));
  run("tar", ["-czf", `${svc}.tgz`, "-C", `${svc}-stage`, "."], art, `tar ${svc}`);
}
// the orchestrator: compiled output + its runtime dependency closure (see package-gateway.mjs)
run(process.execPath, [join(here, "package-gateway.mjs"), ws, art, "gateway.tgz"], here, "package gateway");
// the JWKS publisher: the tutorial's dev tool, deployed as a tiny service next to the others
{ const stage = join(art, "jwks-stage"); mkdirSync(join(stage, "keys"), { recursive: true }); cpSync(join(ws, "dev-jwks.mjs"), join(stage, "dev-jwks.mjs")); cpSync(join(ws, "keys", "jwks.json"), join(stage, "keys", "jwks.json")); run("tar", ["-czf", "jwks.tgz", "-C", "jwks-stage", "."], art, "tar jwks"); }
console.log(JSON.stringify({ workspace: ws, artifacts: readdirSync(art).filter((f) => f.endsWith(".tgz")).map((f) => ({ file: f, bytes: statSync(join(art, f)).size })) }, null, 2));
